/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/*
 * Spec-side black-box experiments (README.md): what they poke, written from
 * the JieLi SDK's register map (vendor/jieli-sdk WL82.h, csfr.h; hwi.h for
 * the interrupt numbers) and, where the SDK has no bit meanings, from the
 * vendored emulator's model (fm1-soc lib.rs, periph.rs, lcd.rs). Spec side
 * only: this file and the images never leave harness/; docs/HARDWARE-SPEC.md
 * cites only their IDs and results.
 */
#ifndef EXP_H
#define EXP_H

typedef unsigned int u32;
typedef unsigned short u16;
typedef unsigned char u8;
typedef int s32;
#define REG(a) (*(volatile u32 *)(a))

/* Results: fixed words in RAM, saved with --ram. */
#define OUT(i) REG(0x01c00100u + 4u * (i))
#define LOG ((volatile u32 *)0x01c01000u)

/* Interrupts: RAM vector table (hwi.h ISR_ENTRY), cpu0's ICFG00.. words
   (csfr.h q32DSP(0)), software latch (ILAT_SET / ILAT_CLR). */
#define VECTOR(n) REG(0x01c7fe00u + 4u * (n))
#define ICFG(n) REG(0x1eef100u + 4u * ((n) >> 3))
#define ICFG_ON(n, prio) (((1u | ((prio) << 1)) & 0xfu) << (((n) & 7u) * 4u))
#define ILAT_SET REG(0x1eef1a0u)
#define ILAT_CLR REG(0x1eef1a4u)
/* The core tick timer (csfr.h TTMR_CON / TTMR_CNT / TTMR_PRD). */
#define TTMR_CON REG(0x1eef0ecu)
#define TTMR_CNT REG(0x1eef0f0u)
#define TTMR_PRD REG(0x1eef0f4u)
#define IRQ_TICK_TMR 3u
#define IRQ_TIMER0 4u
#define IRQ_ALNK 11u
#define IRQ_TIMER5 63u
#define IRQ_SOFT0 120u

/* corex2 (csfr.h): C1_CON, DBG_MSG. */
#define C1_CON REG(0x1eee004u)
#define DBG_MSG REG(0x1eee244u)
#define CORE1_ENTRY REG(0x01c7fff8u)

/* JL_TIMERn (WL82.h): CON, CNT, PRD at +0, +4, +8. */
#define TMR_CON(n) REG(0x10400u + 0x100u * (n))
#define TMR_CNT(n) REG(0x10404u + 0x100u * (n))
#define TMR_PRD(n) REG(0x10408u + 0x100u * (n))

/* JL_PORTx (WL82.h): OUT +0, IN +4. */
#define PA_OUT REG(0x50000u)
#define PA_IN REG(0x50004u)
#define PB_IN REG(0x50044u)
#define PC_OUT REG(0x50080u)
#define PH_OUT REG(0x501c0u)

/* JL_SPI1 (WL82.h): CON, BAUD, BUF, ADR, CNT. */
#define SPI1_CON REG(0x11d00u)
#define SPI1_BUF REG(0x11d08u)
#define SPI1_ADR REG(0x11d0cu)
#define SPI1_CNT REG(0x11d10u)

/* JL_ADC (WL82.h): CON, RES. */
#define ADC_CON REG(0x13100u)
#define ADC_RES REG(0x13104u)

/* JL_ALNK0 (WL82.h): CON0, CON1, CON2, CON3, ADR0..ADR3, LEN. */
#define ALNK_CON0 REG(0x12e00u)
#define ALNK_CON2 REG(0x12e08u)
#define ALNK_ADR3 REG(0x12e1cu)
#define ALNK_LEN REG(0x12e20u)

static inline void irq_on(void)
{
    __asm__ volatile("r0 = 0x100\n\ticfg = r0\n\tsti" ::: "r0");
}

/* Wait about `us` microseconds on TIMER4's 24 MHz count (already running). */
static inline void wait_us(u32 us)
{
    u32 t0 = TMR_CNT(4);
    while (TMR_CNT(4) - t0 < 24u * us) {
    }
}

#endif
/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */

/* Startup for the experiments: both stacks below the vector table, then */
/* main(); when main returns, a halt (interrupts off, a jump to itself). */
	.section .text.start, "ax"
	.globl _start
_start:
	r0 = 0x01c7e000
	ssp = r0
	r0 = 0x01c7d000
	sp = r0
	usp = r0
	call main
	.globl halt
halt:
	cli
1:	goto 1b
/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* The experiments run from the start of the image window (docs/HARNESS.md):
   one section, code and constants, no initialised data. */
ENTRY(_start)
SECTIONS
{
    . = 0x02000000;
    .text : { KEEP(*(.text.start)) *(.text*) *(.rodata*) . = ALIGN(4); image_end = .; }
    .data : { *(.data*) }
    .bss : { *(.bss*) *(COMMON) }
}
ASSERT(SIZEOF(.data) == 0, "experiments have no initialised data")
ASSERT(SIZEOF(.bss) == 0, "experiments keep their state at fixed RAM addresses")
/* SPDX-License-Identifier: MIT */
/* SPDX-FileCopyrightText: 2026 japes98 */
/* E-3: timers and interrupts. TIMER5 with PRD 600 (IRQ 63), TIMER0 with
   prescaler index 2 and PRD 1500 (IRQ 4), the core tick timer with PRD
   1234 (IRQ 3), one software interrupt (IRQ 120); each handler counts.
   TIMER4 runs free; the TIMER5 handler keeps the TIMER4 count between two
   of its interrupts. The main loop sleeps with idle. */
#include "exp.h"

__attribute__((interrupt)) void t5_isr(void)
{
    TMR_CON(5) = 1u | 0x4000u;
    u32 now = TMR_CNT(4);
    if (OUT(0))
        OUT(2) = now - OUT(1);
    OUT(1) = now;
    OUT(0)++;
}

__attribute__((interrupt)) void t0_isr(void)
{
    OUT(4) = TMR_CON(0);             /* CON as the handler sees it */
    TMR_CON(0) = 1u | (2u << 4) | 0x4000u;
    OUT(3)++;
}

__attribute__((interrupt)) void tick_isr(void)
{
    TTMR_CON = 1u | 0x40u;
    OUT(5)++;
}

__attribute__((interrupt)) void soft_isr(void)
{
    ILAT_CLR = 1u;
    OUT(6)++;
}

int main(void)
{
    VECTOR(IRQ_TIMER5) = (u32)t5_isr;
    VECTOR(IRQ_TIMER0) = (u32)t0_isr;
    VECTOR(IRQ_TICK_TMR) = (u32)tick_isr;
    VECTOR(IRQ_SOFT0) = (u32)soft_isr;
    ICFG(IRQ_TIMER5) |= ICFG_ON(IRQ_TIMER5, 3u);
    ICFG(IRQ_TIMER0) |= ICFG_ON(IRQ_TIMER0, 2u);
    ICFG(IRQ_TICK_TMR) |= ICFG_ON(IRQ_TICK_TMR, 1u);
    ICFG(IRQ_SOFT0) |= ICFG_ON(IRQ_SOFT0, 1u);
    TMR_CON(4) = 1u;
    TMR_PRD(5) = 600u;
    TMR_CON(5) = 1u;
    TMR_PRD(0) = 1500u;
    TMR_CNT(0) = 0u;
    TMR_CON(0) = 1u | (2u << 4);
    TTMR_PRD = 1234u;
    TTMR_CON = 1u;
    irq_on();
    ILAT_SET = 1u;
    for (;;)
        __asm__ volatile("idle");
}
HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$HERE/../.." && pwd)
out=${1:?usage: run.sh OUT}

sh "$HERE/build.sh" --check
t=$(sh "$ROOT/harness/ci.sh" tag)
docker image inspect "$t" >/dev/null 2>&1 || sh "$ROOT/harness/ci.sh" image >/dev/null
rm -rf "$out"
mkdir -p "$out"
out=$(cd "$out" && pwd)
docker run --rm --platform linux/amd64 --network none --user "$(id -u):$(id -g)" \
    -v "$HERE:/experiments:ro" -v "$out:/out" "$t" \
    suite /experiments/experiments.suite --out /out/suite
echo "spec experiments: every case matched its golden files"

