    OUT(b + 6) = REG(UNMAPPED);
    REG(UNMAPPED) = 0x5a5a5a5au;
    OUT(b + 7) = REG(UNMAPPED);
    *(volatile u32 *)table = 0x12345678u;
    OUT(b + 8) = *(volatile u32 *)table;
    OUT(b + 9) = (u32)((s32)n / (s32)zero);
    OUT(b + 10) = n / zero;
    OUT(b + 11) = (u32)((s32)n % (s32)zero);
    OUT(b + 12) = n % zero;
    OUT(b + 13) = OUT(1) + OUT(2) + OUT(3);
